#ifndef TST_CROSSFACE_RAY_INTERFACE_VALUE_HPP_
#define TST_CROSSFACE_RAY_INTERFACE_VALUE_HPP_
#include <map>
#include <set>
#include <string>
#include "interface_angular_weights.hpp"
#include "mesh/cubed_sphere/composite_difference.hpp"
namespace interface_probe {
// HOST-only topology experiment. Known normal Cartesian active-cell planes
// extend each actual shell angular ray. Cartesian samples interpolate ONLY
// tangentially; no off-plane normal interpolation or singular-field chart.
struct CrossFaceRayValue {
 using Grid=cubed_sphere::CompositeDifference;
 using Weights=std::map<size_t,Real>;
 struct Node{Real radius;Weights weights;bool Cartesian;};
 struct Diagnostics{std::string status="unbuilt";int face=-1,angular_rays=0,mixed_rays=0,Cartesian_nodes=0,shell_nodes=0,deduplicated_planes=0,unaligned_planes=0;Real value_L1=0,maximum_ray_L1=0,constant_sum_error=0,minimum_bracket_margin=1e9,maximum_query_ray_cube_boundary=0;int angular_donors=0,angular_rank=0;Real angular_condition=0,angular_L1=0,angular_reproduction=0;std::vector<std::string> angular_attempts;};
 Weights weights;Diagnostics diagnostic;
 static Real Radius(const Real*x){Real sum=0;for(int a=0;a<3;++a)sum+=x[a]*x[a];return std::sqrt(sum);}
 static size_t Ordinal(const Grid&g,int block,const int i[3]){return ((size_t(block)*g.n+i[2])*g.n+i[1])*g.n+i[0];}
 static std::array<Real,6> Lagrange(Real t,int first){std::array<Real,6>w{};for(int i=0;i<6;++i){w[i]=1;for(int j=0;j<6;++j)if(i!=j)w[i]*=(t-first-j)/Real(i-j);}return w;}
 static Real L1(const Weights&w){Real sum=0;for(const auto&e:w)sum+=std::abs(e.second);return sum;}
 bool Build(const Grid&g,const Real x[3],Real value_cap=16){weights.clear();diagnostic=Diagnostics{};auto fail=[&](const char*s){diagnostic.status=s;weights.clear();return false;};if(g.n<6||!(value_cap>0)||!std::isfinite(value_cap))return fail("invalid_shape_or_cap");const Real radius=Radius(x);if(!(radius>0&&std::isfinite(radius)))return fail("origin_or_nonfinite_query");diagnostic.face=cubed_sphere::Map{}.Owner(x);Real unit[3];for(int a=0;a<3;++a)unit[a]=x[a]/radius;
  struct NativeRay{size_t atlas;int j,k;std::array<Real,3>direction;};std::vector<NativeRay>rays;std::vector<std::array<Real,3>>directions;for(size_t m=0;m<g.mesh.blocks.size();++m){const auto&block=g.mesh.blocks[m];if(block.face<0||block.layer!=0)continue;for(int k=0;k<g.n;++k)for(int j=0;j<g.n;++j){const Real q[3]={.5,(j+.5)/g.n,(k+.5)/g.n};Real ray[3];g.mesh.Forward(m,q,ray);const Real length=Radius(ray);NativeRay native{m,j,k,{ray[0]/length,ray[1]/length,ray[2]/length}};rays.push_back(native);directions.push_back(native.direction);}}
  cubed_sphere::InterfaceAngularWeights::Row angular_row;bool angular_ready=false;for(int count:{49,64}){if(directions.size()<size_t(count))continue;try{cubed_sphere::InterfaceAngularWeights fit(directions,count);angular_row=fit.Build(unit);diagnostic.angular_attempts.push_back(std::to_string(count)+":ready");angular_ready=true;break;}catch(const std::exception&e){diagnostic.angular_attempts.push_back(std::to_string(count)+":"+e.what());}}if(!angular_ready)return fail("angular_supports_exhausted");diagnostic.angular_donors=angular_row.ids.size();diagnostic.angular_rank=angular_row.rank;diagnostic.angular_condition=angular_row.condition;diagnostic.angular_L1=angular_row.l1;diagnostic.angular_reproduction=angular_row.reproduction;
  for(size_t ir=0;ir<angular_row.ids.size();++ir){const auto&native=rays.at(angular_row.ids[ir]);const size_t atlas=native.atlas;const auto&angular=g.mesh.blocks[atlas];const int face=angular.face,a=face/2,c=(a+1)%3,d=(a+2)%3,j=native.j,k=native.k;const Real sign=face%2?-1:1,ray_u=angular.lo[1]+(j+.5)/g.n*(angular.hi[1]-angular.lo[1]),ray_v=angular.lo[2]+(k+.5)/g.n*(angular.hi[2]-angular.lo[2]),length=std::sqrt(1+ray_u*ray_u+ray_v*ray_v);diagnostic.maximum_query_ray_cube_boundary=std::max(diagnostic.maximum_query_ray_cube_boundary,g.mesh.half_width*length);std::vector<Node>nodes;
   Real minimum_spacing=1e9;for(const auto&b:g.mesh.blocks)if(b.face<0)minimum_spacing=std::min(minimum_spacing,(b.hi[a]-b.lo[a])/g.n);if(!(minimum_spacing>0&&std::isfinite(minimum_spacing)))return fail("Cartesian_planes_unavailable");std::set<long long>plane_keys;int plane_attempts=0;for(const auto&b:g.mesh.blocks)if(b.face<0)for(int i=0;i<g.n;++i){const Real coordinate=b.lo[a]+(i+.5)/g.n*(b.hi[a]-b.lo[a]);if(sign*coordinate<=0)continue;const Real key=(coordinate+g.mesh.half_width)*2/minimum_spacing;const long long integer=std::llround(key);if(std::abs(key-integer)>1e-8)return fail("noncommensurate_normal_planes");plane_keys.insert(integer);++plane_attempts;}diagnostic.deduplicated_planes+=plane_attempts-plane_keys.size();
   for(long long key:plane_keys){const Real coordinate=-g.mesh.half_width+key*minimum_spacing/2,lambda=sign*coordinate;if(!(lambda>0))continue;Real sample[3];sample[a]=coordinate;sample[c]=lambda*ray_u;sample[d]=lambda*ray_v;const int owner=g.mesh.Owner(sample);if(owner<0||g.mesh.blocks[owner].face>=0)return fail("Cartesian_plane_owner");Real q[3];g.mesh.Inverse(owner,sample,q);const Real normal_index=g.n*q[a]-.5;const int aligned=std::llround(normal_index);if(aligned<0||aligned>=g.n||std::abs(normal_index-aligned)>1e-9){++diagnostic.unaligned_planes;continue;}Node node;node.radius=lambda*length;node.Cartesian=true;int begin[2];std::array<Real,6>tw[2];for(int t=0;t<2;++t){const int axis=t?d:c;const Real index=g.n*q[axis]-.5;begin[t]=std::clamp(int(std::floor(index))-2,0,g.n-6);tw[t]=Lagrange(index,begin[t]);}for(int id=0;id<6;++id)for(int ic=0;ic<6;++ic){int indices[3];indices[a]=aligned;indices[c]=begin[0]+ic;indices[d]=begin[1]+id;node.weights[Ordinal(g,owner,indices)]+=tw[0][ic]*tw[1][id];}Real sum=0;for(const auto&e:node.weights)sum+=e.second;node.weights.begin()->second+=1-sum;nodes.push_back(std::move(node));}
   for(size_t m=0;m<g.mesh.blocks.size();++m){const auto&b=g.mesh.blocks[m];if(b.face!=face||b.lo[1]!=angular.lo[1]||b.hi[1]!=angular.hi[1]||b.lo[2]!=angular.lo[2]||b.hi[2]!=angular.hi[2])continue;for(int i=0;i<g.n;++i){const Real q[3]={(i+.5)/g.n,(j+.5)/g.n,(k+.5)/g.n};Real sample[3];g.mesh.Forward(m,q,sample);Node node;node.radius=Radius(sample);node.Cartesian=false;const int indices[3]={i,j,k};node.weights[Ordinal(g,m,indices)]=1;nodes.push_back(std::move(node));}}
   std::sort(nodes.begin(),nodes.end(),[](const Node&a,const Node&b){return a.radius<b.radius;});if(nodes.size()<6)return fail("radial_chain_count");for(size_t i=1;i<nodes.size();++i)if(!(nodes[i].radius>nodes[i-1].radius))return fail("radial_chain_duplicate");auto position=std::lower_bound(nodes.begin(),nodes.end(),radius,[](const Node&a,Real r){return a.radius<r;});const int start=std::clamp(int(position-nodes.begin())-3,0,int(nodes.size())-6);if(!(radius>=nodes[start].radius&&radius<=nodes[start+5].radius))return fail("radial_query_not_bracketed");diagnostic.minimum_bracket_margin=std::min(diagnostic.minimum_bracket_margin,std::min(radius-nodes[start].radius,nodes[start+5].radius-radius));Weights ray;bool Cart=false,Shell=false;for(int i=0;i<6;++i){Real weight=1;for(int l=0;l<6;++l)if(i!=l)weight*=(radius-nodes[start+l].radius)/(nodes[start+i].radius-nodes[start+l].radius);const auto&node=nodes[start+i];Cart=Cart||node.Cartesian;Shell=Shell||!node.Cartesian;(node.Cartesian?diagnostic.Cartesian_nodes:diagnostic.shell_nodes)++;for(const auto&e:node.weights)ray[e.first]+=weight*e.second;}++diagnostic.angular_rays;diagnostic.mixed_rays+=Cart&&Shell;diagnostic.maximum_ray_L1=std::max(diagnostic.maximum_ray_L1,L1(ray));const Real angular_weight=angular_row.weights[ir];for(const auto&e:ray)weights[e.first]+=angular_weight*e.second;
  }
  Real sum=0;for(const auto&e:weights)sum+=e.second;diagnostic.constant_sum_error=std::abs(sum-1);if(!(diagnostic.constant_sum_error<=1e-10))return fail("constant_reproduction");weights.begin()->second+=1-sum;diagnostic.value_L1=L1(weights);if(!(diagnostic.value_L1<=value_cap&&std::isfinite(diagnostic.value_L1)))return fail("value_amplification");diagnostic.status="ready";return true;}
};
}
#endif
